--
-- TOC entry 268 (class 1259 OID 73682)
-- Name: v_resumen_especies; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_resumen_especies AS
SELECT
    NULL::integer AS id_especie,
    NULL::character varying(150) AS nombre_cientifico,
    NULL::character varying(150) AS nombre_comun,
    NULL::character varying(5) AS categoria_uicn,
    NULL::bigint AS total_registros,
    NULL::date AS ultima_observacion,
    NULL::timestamp without time zone AS fecha_creacion;



--
-- TOC entry 269 (class 1259 OID 73687)
-- Name: v_resumen_simulaciones; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_resumen_simulaciones AS
 SELECT s.id_simulacion,
    s.nombre,
    s.tipo,
    ec.codigo_ssp,
    e.nombre_cientifico AS especie,
    s."año_inicio",
    s."año_fin",
    s.estado,
    s.progreso,
    s.fecha_inicio,
    s.fecha_fin,
    u.nombre_completo AS usuario_creador
   FROM (((public.simulaciones s
     LEFT JOIN public.escenarios_climaticos ec ON ((s.id_escenario = ec.id_escenario)))
     LEFT JOIN public.especies e ON ((s.id_especie = e.id_especie)))
     LEFT JOIN public.usuarios u ON ((s.id_usuario = u.id_usuario)));



