--
-- TOC entry 6362 (class 2618 OID 73685)
-- Name: v_resumen_especies _RETURN; Type: RULE; Schema: public; Owner: postgres
--

CREATE OR REPLACE VIEW public.v_resumen_especies AS
 SELECT e.id_especie,
    e.nombre_cientifico,
    e.nombre_comun,
    e.categoria_uicn,
    count(r.id_registro) AS total_registros,
    max(r.fecha_observacion) AS ultima_observacion,
    e.fecha_creacion
   FROM (public.especies e
     LEFT JOIN public.registros_presencia r ON ((e.id_especie = r.id_especie)))
  GROUP BY e.id_especie, e.nombre_cientifico, e.nombre_comun, e.categoria_uicn;


